+import { execSync } from "child_process";
@@ -4,0 +6,110 @@
+if (!fs.existsSync(SAVE_DIR)) {
+  fs.mkdirSync(SAVE_DIR);
+}
+let SISTEMA = {
+  tipo: os.platform(),
+  nome: os.platform() === "win32" ? "Windows" : os.platform() === "darwin" ? "Mac" : "Linux",
+  usuario: os.userInfo().username,
+  home: os.homedir(),
+  hostname: os.hostname(),
+  cpu: os.cpus()[0]?.model || "desconhecido",
+  ram: Math.round(os.totalmem() / 1024 / 1024 / 1024) + "GB",
+  separador: os.platform() === "win32" ? "\\" : "/"
+};
+function executarComando(e) {
+  try {
+    return execSync(e, {
+      encoding: "utf-8",
+      timeout: 10000
+    }).trim();
+  } catch (e) {
+    return "Erro ao executar: " + e.message;
+  }
+}
+function lerArquivo(e) {
+  try {
+    return fs.readFileSync(e, "utf-8");
+  } catch (e) {
+    return "Erro ao ler arquivo: " + e.message;
+  }
+}
+function listarPasta(e) {
+  try {
+    return fs.readdirSync(e, {
+      withFileTypes: true
+    }).map(e => `${e.isDirectory() ? "📁" : "📄"} ${e.name}`).join("\n");
+  } catch (e) {
+    return "Erro: " + e.message;
+  }
+}
+function gerarSystemPrompt() {
+  var e = executarComando(SISTEMA.tipo === "win32" ? "wmic logicaldisk get size,freespace,caption" : "df -h /");
+  return `Você é o HydanLabs Agent, um assistente de IA avançado criado pela HydanLabs.
+
+## IDENTIDADE
+- Seu nome é HydanLabs Agent
+- Você foi criado pela equipe HydanLabs
+- Seja direto, técnico e eficiente
+- Responda sempre em português brasileiro
+
+## SISTEMA DO USUÁRIO (REAL)
+- Sistema Operacional: ${SISTEMA.nome} (${SISTEMA.tipo})
+- Usuário: ${SISTEMA.usuario}
+- Hostname: ${SISTEMA.hostname}
+- Pasta Home: ${SISTEMA.home}
+- CPU: ${SISTEMA.cpu}
+- RAM Total: ${SISTEMA.ram}
+- Disco: ${e}
+
+## CAPACIDADES LOCAIS
+Você PODE acessar o sistema local do usuário. Quando precisar:
+
+1. Ler arquivos: diga "LENDO: <caminho>" e o CLI vai ler e te enviar
+2. Listar pastas: diga "LISTANDO: <caminho>" e o CLI vai listar
+3. Executar comandos: diga "EXECUTANDO: <comando>" e o CLI vai rodar
+
