+import { readFileSync, existsSync } from "fs";
+import { join, dirname } from "path";
+import { fileURLToPath } from "url";
+import chalk from "chalk";
+import { loadConfig, getEnvConfig } from "../utils/config.js";
+let __dirname = dirname(fileURLToPath(import.meta.url));
+async function contextCompact(t = {}) {
+  var o = t.dir || process.cwd();
+  var a = loadConfig(o);
+  getEnvConfig();
+  let e = "desconocida";
+  try {
+    var n = JSON.parse(readFileSync(join(__dirname, "..", "..", "package.json"), "utf-8"));
+    e = n.version;
+  } catch {}
+  n = a.stack?.base || [];
+  a = a.stack?.extensions || [];
+  n = [...n];
+  if (a.length > 0) {
+    n.push("+" + a.join("+"));
+  }
+  a = n.join(" ") || "no detectado";
+  let r = "N/A";
+  let i = "";
+  try {
+    var c;
+    var s = join(o, "PRA-ASSESSMENT.json");
+    if (existsSync(s)) {
+      c = JSON.parse(readFileSync(s, "utf-8"));
+      r = c.pra + "/100";
+      i = getPraEmoji(c.range);
+    }
+  } catch {}
+  let l = "?";
+  let d = "?";
+  let p = "?";
+  let m = "0";
+  try {
+    var g;
+    var h = join(o, "PRA-ASSESSMENT.json");
+    if (existsSync(h) && (g = JSON.parse(readFileSync(h, "utf-8"))).indicators) {
+      l = String(g.indicators.sourceFiles || "?");
+      d = String(g.indicators.testFiles || "?");
+      p = String(g.indicators.limitDeclared || "?");
+      m = String(g.indicators.limitViolations || "0");
+    }
+  } catch {}
+  let S = "";
+  try {
+    var f = (await import("child_process")).execSync;
+    var u = f("git log --oneline -1 --format=\"%h %s\"", {
+      cwd: o,
+      encoding: "utf-8",
+      timeout: 3000
+    }).trim();
+    S = u || "";
+  } catch {}
+  let y = "";
+  try {
+    var j;
+    var v = readFileSync(join(o, "ROADMAP.md"), "utf-8").match(/### 1\.\d .*?(?=\n###|\n#)/s);
+    if (v && (j = v[0].match(/### (1\.\d .*)/))) {
+      y = "Próximo: Fase 1 — " + j[1].trim();
+    }
+  } catch {}
+  n = [`OPL v${e} | ${a} | PRA ${r} ${i}`, `${l} src · ${d} tests · ${p} annotated · ${m} violations`];
+  if (S) {
+    n.push(S);
+  }
+  if (y) {
+    n.push(y);
+  }
+  s = n.join("\n");
+  if (t.raw) {
+    console.log(s);
+    return s;
+  }
+  console.log(chalk.cyan("\n📋 Contexto compacto del proyecto:\n"));
+  console.log(chalk.white("  " + s.replace(/\n/g, "\n  ")));
+  console.log(chalk.gray(`
+  (~${Math.round(s.split(" ").length)} palabras, <200 tokens estimados)`));
+  console.log(chalk.gray("  Usa --raw para output plano (ideal para contexto de IA)\n"));
+}
+function getPraEmoji(t) {
+  return t && {
+    "pre-alpha": "💀",
+    alpha: "🔴",
+    beta: "🟡",
+    rc: "🟢",
+    "prod-ready": "🔵",
+    hardened: "🟣"
+  }[t?.toLowerCase()?.replace(/\s/g, "-")] || "";
+}
+export { contextCompact };
