diff -N -U 0 -r a/schemas/execute_sandbox.json b/schemas/execute_sandbox.json
--- a/schemas/execute_sandbox.json
+++ b/schemas/execute_sandbox.json
@@ -0,0 +1,102 @@
+{
+  "$schema": "http://json-schema.org/draft-07/schema#",
+  "title": "Execute Sandbox Contract",
+  "description": "Contrato de entrada y salida para la herramienta execute_sandbox MCP",
+  "type": "object",
+  "required": ["mode", "domain", "command", "constraints"],
+  "properties": {
+    "mode": {
+      "type": "string",
+      "enum": ["local-fast", "docker-ephemeral"],
+      "description": "Nivel de aislamiento. local-fast para validaciones sin estado, docker-ephemeral para ejecución de código no confiable o que muta estado."
+    },
+    "domain": {
+      "type": "string",
+      "enum": ["node", "java", "python", "unity", "generic"],
+      "description": "Dominio de ejecución para rutear al adaptador correcto."
+    },
+    "projectRoot": {
+      "type": "string",
+      "description": "Ruta absoluta o relativa al proyecto a ejecutar. Por defecto el CWD."
+    },
+    "workspace": {
+      "type": "object",
+      "properties": {
+        "readOnly": { "type": "boolean", "default": false },
+        "mountTemp": { "type": "boolean", "default": true }
+      }
+    },
+    "command": {
+      "type": "object",
+      "required": ["kind", "value"],
+      "properties": {
+        "kind": {
+          "type": "string",
+          "enum": ["test", "lint", "build", "run", "custom"]
+        },
+        "value": {
+          "type": "string",
+          "description": "Comando exacto a ejecutar, ej: npm test"
+        }
+      }
+    },
+    "files": {
+      "type": "object",
+      "properties": {
+        "changed": { "type": "array", "items": { "type": "string" } },
+        "entrypoint": { "type": "string" }
+      }
+    },
+    "constraints": {
+      "type": "object",
+      "required": ["timeoutMs"],
+      "properties": {
+        "timeoutMs": { "type": "integer", "minimum": 100, "maximum": 300000 },
+        "memoryMb": { "type": "integer", "minimum": 128 },
+        "network": { "type": "boolean", "default": false },
+        "allowWrite": { "type": "boolean", "default": true }
+      }
+    },
+    "filters": {
+      "type": "object",
+      "properties": {
+        "stdout": { "type": "string", "enum": ["raw", "clean"] },
+        "stderr": { "type": "string", "enum": ["raw", "clean"] },
+        "stackTrace": { "type": "string", "enum": ["raw", "source-linked"] }
+      }
+    },
+    "expected": {
+      "type": "object",
+      "properties": {
+        "exitCodes": {
+          "type": "array",
+          "items": { "type": "integer" },
+          "default": [0]
+        },
+        "artifacts": {
+          "type": "array",
+          "items": { "type": "string" }
+        }
+      }
+    }
+  },
+  "allOf": [
+    {
+      "if": {
+        "properties": { "mode": { "const": "local-fast" } }
+      },
+      "then": {
+        "type": "object",
+        "properties": {
+          "constraints": {
+            "type": "object",
+            "properties": {
+              "timeoutMs": { "type": "integer", "maximum": 30000 }
+            }
+          }
+        }
+      }
+    }
+  ],
+  "additionalProperties": false
+}
