+function resolveUid(e) {
+  e = spawnSync("id", ["-u", e], {
+    encoding: "utf8"
+  });
+  if (e.status !== 0) {
+    return "";
+  } else {
+    return String(e.stdout || "").trim();
+  }
+}
+function resolveHomeDir(e) {
+  e = spawnSync("getent", ["passwd", e], {
+    encoding: "utf8"
+  });
+  return e.status === 0 && String(e.stdout || "").trim().split(":")[5] || "";
